/**
 * SWITCH REGISTRY — build 2026-10-08 S-1 (simplify.md §4 stage 0; owner: "yes lets do all this").
 *
 * The ONE list of every env switch the code reads — backend `*_DISABLED` / `*_ENABLED` /
 * `*_ENFORCE` names in backend/src and the frontend's build-time `NEXT_PUBLIC_*` switches —
 * with, per switch: the owner AREA, the KIND, the date it was ADDED, the EXPIRY of a release
 * switch, and — when docker-compose.app.yml does not deliver it — WHY (`notForwarded`).
 *
 * Why it exists (simplify.md §1.1, measured 2026-10-08): compose env lists are explicit
 * ${VAR} interpolation and backend/.dockerignore drops .env, so a switch compose does not
 * list can never be set in prod — 461 of the 696 the backend read were in that state,
 * including the re-arm switches of the 2026-09-11 gate flip. Nothing checked it, the count
 * grew ~19 a day and only 3 had ever been removed.
 *
 * KINDS (Unleash / Hodgson taxonomy, simplify.md §2.1):
 *   release — restores the PREVIOUS behaviour of a shipped change ("… =1 restores …").
 *             Temporary: carries `expires`; past it CI fails until the switch is deleted
 *             (inline the default, drop the dead branch + its tests) or the expiry is
 *             extended with a reason.
 *   ops     — a permanent operational kill switch: turns a subsystem off to degrade
 *             gracefully (a cron, an external provider / connector, analytics, spend).
 *             Never expires; MUST be forwarded to be worth anything.
 *   opt-in  — arms a non-default behaviour (`*_ENABLED` / `*_ENFORCE`). No expiry required;
 *             an opt-in prod cannot set is dead code (its OFF default is the only branch).
 *
 * CI (switch-registry.test.ts → scripts/switch-scan.ts) — every check is a hard failure
 * with the fix in the message:
 *   (a) every switch the code reads is a row here, and every row is still read;
 *   (b) a row without `notForwarded` is forwarded by docker-compose.app.yml (backend or
 *       worker environment; frontend: build arg AND `ARG` in frontend/Dockerfile), and a
 *       row WITH it is not (a stale marker fails too);
 *   (c) a release switch past `expires` fails (a TIME BOMB by design — Hodgson 2017);
 *   (d) the row count equals the last SWITCH_COUNT_LEDGER line, and a line that RAISES the
 *       count carries a justification — a PR may not add switches silently.
 *
 * Maintenance: `npm run switches:sync` (backend/) adds rows for new switches (kind by
 * suffix, added = today, a release expiry of RELEASE_LIFETIME_DAYS) and drops rows for
 * switches no longer read; it never writes a `notForwarded` marker or a ledger
 * justification — those are decisions. `npm run switches:check` prints the violations.
 *
 * Pure leaf: no imports, no I/O — the scan lives in backend/scripts/switch-scan.ts.
 */
export type SwitchKind = 'release' | 'ops' | 'opt-in';
export interface SwitchSpec {
  name: string;
  /** Owner area: the module directory of the first file that reads it ('frontend' for NEXT_PUBLIC_*). */
  area: string;
  kind: SwitchKind;
  /** ISO date the name first appeared in source. */
  added: string;
  /** release: required — CI fails after this ISO date. ops: never. opt-in: optional. */
  expires?: string;
  /** NEXT_PUBLIC_* build-time switch (forwarded through the frontend build args). */
  side?: 'frontend';
  /** Why docker-compose.app.yml does not forward it. Absent ⇒ it must be forwarded. */
  notForwarded?: string;
}
/** Release lifetime for a NEW release switch (simplify.md Option A lint (b): default 21 days). */
export const RELEASE_LIFETIME_DAYS = 21;
/**
 * Expiry floor for the release switches that existed when the registry was created: stage 4
 * of the simplify.md plan (week 5 — "lints become BLOCKING"). Before it the inert ones are
 * purged in stage 1 and the rest are retired or re-classified.
 */
export const EXISTING_RELEASE_EXPIRY_FLOOR = '2026-11-12';
/**
 * The lane-depth flip's ENV ROLLBACK, re-dated together (2026-10-20, owner "yes do all of this"). From 2026-10-20
 * the turn-plan store flags go act fleet-wide in stages — laneChecker first, laneFailOpen once turn_plan decision
 * failures stay under 1 % for 7 d, laneResearch once the guest / allowance fix ships — and these release switches
 * become the per-box hard stop behind each step (the store flip is the fast lever; an env flag is the one that
 * survives a bad store row). They were due 2026-11-12 (EXISTING_RELEASE_EXPIRY_FLOOR), i.e. INSIDE the staged
 * flip's bake, which would have forced the rollback out before the last step was measured. The date = the staged
 * flips (~2 weeks, to ~2026-11-03) + one full release lifetime of bake on the last one (RELEASE_LIFETIME_DAYS, 21 d
 * ⇒ 2026-11-24) + one week of slack for the readout. Still release kind: when it lands, each is deleted (default
 * inlined) or re-dated again with a reason. Rows in SWITCHES carry the literal date (sync renders literals);
 * switch-registry.test.ts pins every name here to it.
 */
export const LANE_DEPTH_ROLLBACK_EXPIRY = '2026-12-01';
/**
 * RETAINED ESCAPE HATCHES — re-classified 2026-11-01 by supervisor ruling, NOT deletion candidates.
 * These four are release-kind rows that reached EXISTING_RELEASE_EXPIRY_FLOOR (2026-11-12) without
 * being deleted, because each is the last per-box hard stop behind a live ACT/store flip: deleting
 * it would remove the only lever that restores safe behaviour without a deploy.
 *
 *   DECISION_GATE_<*>_ACT_CAP_DISABLED  — the DYNAMIC template family (decision-gate-modes.ts
 *     actCapLiftEnv builds `DECISION_GATE_${purpose}_ACT_CAP_DISABLED`). A family row cannot be
 *     deleted to a literal: no single env name covers every purpose. It lifts a purpose registry
 *     act cap on ONE process, i.e. it is the per-box undo of an act flip.
 *   SESSION_TOPOLOGY_DISABLED — the live ACT-gate kill switch for session_topology. Turning the
 *     decision layer off must not require a deploy; this env flag is that seam.
 *   CODING_SEAT_FALLBACK_DISABLED — read by bracket access through the on() helper, so a name grep
 *     cannot see every reader; it disables seat fallback on one box while a bad provider is triaged.
 *   VIEW_IMAGE_TOOL_DISABLED — an instance-level operator disable reached through a helper at five
 *     production sites; it turns the vision tool off without shipping a build.
 *
 *   EXTENDED 2026-11-02 (ticket c5fcbbfb) by two rows that a bare-`process.env.<NAME>` grep reports as
 *   having ZERO production readers and that were therefore being hand-excluded from the delete cohort as
 *   "never wired". That reading is WRONG and the exclusion was for the wrong reason: both are read by a
 *   production helper, and both were merely NOT FORWARDED, i.e. a real kill switch whose lever could not
 *   be pulled in production without a deploy. They are now forwarded (backend + worker) and retained:
 *   SEAT_GOVERNS_SESSIONS_DISABLED — read inside seat-governance.ts through the exported
 *     SEAT_GOVERNS_SESSIONS_DISABLED_ENV const (bracket access), consumed by seatGovernsSessionsDisabled()
 *     at three production seams (coding-data stamping, run-executor precedence, the admin viewerPick).
 *   LEAD_SEAT_FALLBACK_DISABLED — read inside helper-seat.ts through the on() helper, consumed by
 *     leadSeatFallbackDisabled() at six agent.ts seams; it ORs CODING_SEAT_FALLBACK_DISABLED and is the
 *     per-box hard stop that disables lead-seat failover while a bad provider is triaged.
 *   WHY THE ROW MARKER LIED: NF_INERT says "a deletion candidate" and reads as "nothing reads this" —
 *   it only ever meant "compose cannot deliver it". A read-but-unforwarded release row is the OPPOSITE of
 *   dead config: it is a live guard behind a lever nobody can reach. The scanner (scripts/switch-scan.ts)
 *   is the authority on reads — it parses the AST and sees a name in a string literal, a const, or a
 *   bracket access; a name grep does not. Never classify a row by `process.env.<NAME>` count alone.
 *
 * One justified re-bake to RETAINED_ESCAPE_HATCH_EXPIRY, with the READOUT on that same date: on
 * 2026-12-15 each is re-judged — delete it (if the flip behind it has shipped and baked) or re-date
 * it again with a fresh reason. Rows in SWITCHES carry the literal date (sync renders literals);
 * switch-registry.test.ts pins every name here to it. Count is UNCHANGED by a re-bake: nothing is
 * added or removed, so SWITCH_COUNT_LEDGER gains a same-count line recording the re-bake.
 */
export const RETAINED_ESCAPE_HATCH_EXPIRY = '2026-12-15';
export const RETAINED_ESCAPE_HATCH_SWITCHES: readonly string[] = [
  'CODING_SEAT_FALLBACK_DISABLED',
  'HELPER_SEAT_FALLBACK_DISABLED',
  'LEAD_SEAT_FALLBACK_DISABLED',
  'SEAT_GOVERNS_SESSIONS_DISABLED',
  'SESSION_TOPOLOGY_DISABLED',
  'VIEW_IMAGE_TOOL_DISABLED',
];
/** The DYNAMIC family twin of the list above — a pattern, so it lives in SWITCH_FAMILIES, not SWITCHES. */
export const RETAINED_ESCAPE_HATCH_FAMILY = 'DECISION_GATE_<*>_ACT_CAP_DISABLED';
