// ── pure checks ──────────────────────────────────────────────────────────────────────────
export type SwitchViolationKind =
  | 'unregistered' | 'unread' | 'duplicate' | 'unsorted' | 'malformed'
  | 'not_forwarded' | 'forwarded_marked' | 'half_forwarded'
  | 'expired' | 'missing_expiry'
  | 'count_mismatch' | 'raise_unjustified' | 'ledger_malformed';
export interface SwitchViolation { kind: SwitchViolationKind; name?: string; message: string }
export interface SwitchScanInput {
  /** backend switch name → files that read it */
  backend: Map<string, string[]>;
  /** dynamic family pattern (with `<*>`) → files that build it (optional: older callers) */
  families?: Map<string, string[]>;
  /** NEXT_PUBLIC_* switch name → files that read it */
  frontend: Map<string, string[]>;
  compose: { backend: Set<string>; worker: Set<string>; frontendArgs: Set<string> };
  frontendDockerArgs: Set<string>;
}
const ISO_DATE = /^\d{4}-\d{2}-\d{2}$/;
const SWITCH_NAME = /^[A-Z][A-Z0-9_]*_(DISABLED|ENABLED|ENFORCE)$/;
export const MIN_RAISE_JUSTIFICATION_CHARS = 30;
export function addDays(iso: string, days: number): string {
  const d = new Date(`${iso}T00:00:00Z`);
  d.setUTCDate(d.getUTCDate() + days);
  return d.toISOString().slice(0, 10);
}
/** The kind a NEW switch gets from its suffix (sync default; a human re-classifies). */
export function defaultKindFor(name: string): SwitchKind {
  return /_(ENABLED|ENFORCE)$/.test(name) ? 'opt-in' : 'release';
}
/** Is the switch delivered to prod by compose? */
export function isForwarded(spec: Pick<SwitchSpec, 'name' | 'side'>, scan: Pick<SwitchScanInput, 'compose' | 'frontendDockerArgs'>): boolean {
  if (spec.side === 'frontend') return scan.compose.frontendArgs.has(spec.name) && scan.frontendDockerArgs.has(spec.name);
  return scan.compose.backend.has(spec.name) || scan.compose.worker.has(spec.name);
}
/**
 * Every violation of checks (a)–(d), each with the fix. Pure: `today` is an ISO date; the
 * registry and ledger default to this module's tables.
 */
export function switchRegistryViolations(
  scan: SwitchScanInput,
  today: string,
  registry: readonly SwitchSpec[] = SWITCHES,
  ledger: readonly SwitchCountLine[] = SWITCH_COUNT_LEDGER,
  families: readonly SwitchFamilySpec[] = SWITCH_FAMILIES,
): SwitchViolation[] {
  const out: SwitchViolation[] = [];
  // (a) for dynamic families
  if (scan.families) {
    const rows = new Set(families.map(f => f.pattern));
    for (const [p, files] of scan.families) {
      if (!rows.has(p)) out.push({ kind: 'unregistered', name: p, message: `${files.slice(0, 3).join(', ')} BUILDS the switch family ${p} — add a SWITCH_FAMILIES row (pattern, area, kind, added, expires for release, notForwarded reason).` });
    }
    for (const f of families) {
      if (!scan.families.has(f.pattern)) out.push({ kind: 'unread', name: f.pattern, message: `SWITCH_FAMILIES row ${f.pattern} is no longer built by the code — drop it.` });
    }
  }
  for (const f of families) {
    if (f.kind === 'release' && (!f.expires || !ISO_DATE.test(f.expires))) out.push({ kind: 'missing_expiry', name: f.pattern, message: `switch family ${f.pattern} is release — give it an \`expires\`.` });
    else if (f.kind !== 'ops' && f.expires && f.expires < today) out.push({ kind: 'expired', name: f.pattern, message: `switch family ${f.pattern} expired on ${f.expires} — delete it (inline the default) or extend \`expires\` with a reason.` });
    if (!f.notForwarded || f.notForwarded.trim().length < 10) out.push({ kind: 'malformed', name: f.pattern, message: `switch family ${f.pattern} needs a notForwarded reason (compose cannot forward a pattern).` });
  }
  const byName = new Map<string, SwitchSpec>();
  let prev = '';
  for (const s of registry) {
    if (byName.has(s.name)) out.push({ kind: 'duplicate', name: s.name, message: `${s.name} is registered twice — keep one row.` });
    byName.set(s.name, s);
    if (s.name < prev) out.push({ kind: 'unsorted', name: s.name, message: `${s.name} is out of order — SWITCHES is sorted by name (npm run switches:sync sorts it).` });
    prev = s.name;
    const bad: string[] = [];
    if (!SWITCH_NAME.test(s.name)) bad.push('name must end _DISABLED / _ENABLED / _ENFORCE');
    if (!['release', 'ops', 'opt-in'].includes(s.kind)) bad.push(`kind '${s.kind}' is not release / ops / opt-in`);
    if (!ISO_DATE.test(s.added)) bad.push(`added '${s.added}' is not YYYY-MM-DD`);
    if (s.expires !== undefined && !ISO_DATE.test(s.expires)) bad.push(`expires '${s.expires}' is not YYYY-MM-DD`);
    if (s.kind === 'ops' && s.expires !== undefined) bad.push('an ops kill switch never expires — drop `expires` or make it release');
    if (!s.area) bad.push('area is empty');
    if (s.notForwarded !== undefined && s.notForwarded.trim().length < 10) bad.push('notForwarded must say why (one sentence)');
    if ((s.side === 'frontend') !== s.name.startsWith('NEXT_PUBLIC_')) bad.push("side: 'frontend' goes with (and only with) a NEXT_PUBLIC_* name");
    if (bad.length) out.push({ kind: 'malformed', name: s.name, message: `${s.name}: ${bad.join('; ')}.` });
  }
  // (a) code ⇄ registry
  const read = new Map<string, { side?: 'frontend'; files: string[] }>();
  for (const [n, files] of scan.backend) read.set(n, { files });
  for (const [n, files] of scan.frontend) if (!read.has(n)) read.set(n, { side: 'frontend', files });
  for (const [n, r] of read) {
    if (!byName.has(n)) out.push({ kind: 'unregistered', name: n, message: `${n} is read by ${r.files.slice(0, 3).join(', ')} but is not in SWITCHES — run \`npm run switches:sync\` (backend/), then forward it in docker-compose.app.yml or give it a notForwarded reason, and add a SWITCH_COUNT_LEDGER line saying why a switch is needed.` });
  }
  for (const s of registry) {
    if (!read.has(s.name)) out.push({ kind: 'unread', name: s.name, message: `${s.name} is registered but no longer read by the code — drop its row (\`npm run switches:sync\`) and append a SWITCH_COUNT_LEDGER line.` });
  }
  // (b) forwarding
  for (const s of registry) {
    if (!read.has(s.name)) continue;
    const fwd = isForwarded(s, scan);
    if (s.side === 'frontend' && !fwd && (scan.compose.frontendArgs.has(s.name) || scan.frontendDockerArgs.has(s.name))) {
      out.push({ kind: 'half_forwarded', name: s.name, message: `${s.name} is half-forwarded: a NEXT_PUBLIC_* switch needs BOTH a frontend build arg in docker-compose.app.yml AND \`ARG ${s.name}=\` + \`ENV ${s.name}=$${s.name}\` in frontend/Dockerfile.` });
      continue;
    }
    if (!fwd && s.notForwarded === undefined) {
      out.push({ kind: 'not_forwarded', name: s.name, message: `${s.name} cannot reach prod: docker-compose.app.yml does not forward it (${s.side === 'frontend' ? 'frontend build args + frontend/Dockerfile ARG' : 'backend and worker environment'}). Forward it, or set notForwarded to the reason it never needs to be set in prod.` });
    }
    if (fwd && s.notForwarded !== undefined) {
      out.push({ kind: 'forwarded_marked', name: s.name, message: `${s.name} is forwarded by docker-compose.app.yml now — drop its notForwarded marker.` });
    }
  }
  // (c) expiry
  for (const s of registry) {
    if (s.kind === 'release' && !s.expires) out.push({ kind: 'missing_expiry', name: s.name, message: `${s.name} is a release switch with no \`expires\` — give it one (added + ${RELEASE_LIFETIME_DAYS} days by default).` });
    if (s.kind !== 'ops' && s.expires && ISO_DATE.test(s.expires) && s.expires < today) {
      out.push({ kind: 'expired', name: s.name, message: `${s.name} (${s.kind}, area ${s.area}) expired on ${s.expires}. Delete it: inline its default, drop the dead branch and the tests that set it, remove its row and append a SWITCH_COUNT_LEDGER line. If it must stay, either re-classify it as an ops kill switch (and forward it) or extend \`expires\` with a one-line reason in the same commit.` });
    }
  }
  // (d) count ratchet
  if (ledger.length === 0) {
    out.push({ kind: 'ledger_malformed', message: 'SWITCH_COUNT_LEDGER is empty — it must end with a line whose count equals SWITCHES.length.' });
  } else {
    ledger.forEach((l, i) => {
      if (!ISO_DATE.test(l.on) || !Number.isInteger(l.count) || l.count < 0) out.push({ kind: 'ledger_malformed', message: `SWITCH_COUNT_LEDGER line ${i + 1} is malformed (on: YYYY-MM-DD, count: a non-negative integer).` });
      if (i > 0 && l.count > ledger[i - 1].count && l.why.trim().length < MIN_RAISE_JUSTIFICATION_CHARS) {
        out.push({ kind: 'raise_unjustified', message: `SWITCH_COUNT_LEDGER line ${i + 1} raises the switch count ${ledger[i - 1].count} → ${l.count} without a justification: name the new switch(es) and why a switch — not an eval case or a unit test — is needed (≥ ${MIN_RAISE_JUSTIFICATION_CHARS} chars).` });
      }
    });
    const last = ledger[ledger.length - 1];
    if (last.count !== registry.length) {
      const up = registry.length > last.count;
      out.push({ kind: 'count_mismatch', message: `SWITCHES has ${registry.length} rows but the last SWITCH_COUNT_LEDGER line says ${last.count}. ${up ? `A change may not raise the switch count silently: append { on, count: ${registry.length}, why } naming the new switch(es) and why each needs a switch.` : `Switches were removed: append { on, count: ${registry.length}, why: 'removed …' }.`}` });
    }
  }
  return out;
}
/**
 * Compose entries that forward a switch-shaped name NO code reads any more (a deleted
 * switch whose compose line was left behind). Warning only — compose is edited by the
 * integrator, so a deletion PR cannot fail on it; the CI test and `switches:check` print it.
 */
export function staleForwards(scan: SwitchScanInput): string[] {
  const out: string[] = [];
  for (const n of new Set([...scan.compose.backend, ...scan.compose.worker])) {
    if (SWITCH_NAME.test(n) && !scan.backend.has(n)) out.push(n);
  }
  for (const n of scan.compose.frontendArgs) {
    if (n.startsWith('NEXT_PUBLIC_') && SWITCH_NAME.test(n) && !scan.frontend.has(n)) out.push(n);
  }
  return out.sort();
}
/** Release switches whose expiry falls within `days` of today (the CI prints these as a warning). */
export function expiringSoon(today: string, days: number, registry: readonly SwitchSpec[] = SWITCHES): SwitchSpec[] {
  const horizon = addDays(today, days);
  return registry.filter(s => s.kind !== 'ops' && !!s.expires && s.expires >= today && s.expires <= horizon);
}
/** Registry summary (counts by kind / forwarding) — for the CLI report and the owner briefing later. */
export function switchRegistrySummary(registry: readonly SwitchSpec[] = SWITCHES): { total: number; byKind: Record<SwitchKind, number>; notForwarded: number; frontend: number } {
  const byKind: Record<SwitchKind, number> = { release: 0, ops: 0, 'opt-in': 0 };
  let nf = 0;
  let fe = 0;
  for (const s of registry) { byKind[s.kind]++; if (s.notForwarded !== undefined) nf++; if (s.side === 'frontend') fe++; }
  return { total: registry.length, byKind, notForwarded: nf, frontend: fe };
}
